function BikeCard({ bike, unlockBike }) {
  return (
    <div className="bg-white p-4 shadow rounded border">
      <h3 className="text-lg font-semibold text-blue-700">Bike #{bike.bikeId}</h3>
      <p>Status: <span className="font-bold">{bike.status}</span></p>
      <p>Battery: {bike.batteryLevel}%</p>

      {bike.status === "Available" ? (
        <button
          onClick={() => unlockBike(bike.bikeId)}
          className="bg-green-600 text-white px-3 py-2 rounded mt-3"
        >
          Unlock
        </button>
      ) : (
        <button className="bg-gray-400 text-white px-3 py-2 rounded mt-3 cursor-not-allowed">
          Unavailable
        </button>
      )}
    </div>
  );
}

export default BikeCard;
